222	
223	    //declaring the other bag
224	    var theOtherBag : MultisetImplementationWithMap;
225	    theOtherBag := new MultisetImplementationWithMap.MultisetImplementationWithMap();
226	
227	    // equals test - unequal bags
228	    var b:= this.equals(theOtherBag);
229	    assert b == false;
